// Check if this is a regular WhatsApp message (not a Flow request)
if (body?.entry) {
  const entry = body.entry[0];
  const changes = entry?.changes?.[0];
  const value = changes?.value;
  const messages = value?.messages;

  if (messages && messages.length > 0) {
    const message = messages[0];
    const from = message.from;
    const messageType = message.type;

    // Handle interactive button replies
    if (messageType === 'interactive' && message.interactive?.type === 'button_reply') {
      const buttonId = message.interactive.button_reply.id;
      const buttonTitle = message.interactive.button_reply.title;
      const parts = buttonId.split('_');
      const action = parts[0];
      const recordId = parts.slice(1).join('_');

      return {
        json: {
          messageType: 'button_reply',
          action: action,
          recordId: recordId,
          customerPhone: from,
          buttonTitle: buttonTitle,
          isRegularMessage: true
        }
      };
    }

    // Handle text messages
    if (messageType === 'text') {
      return {
        json: {
          messageType: 'text_message',
          from: from,
          text: message.text?.body || '',
          isRegularMessage: true
        }
      };
    }

    // Other message types
    return {
      json: {
        messageType: messageType,
        from: from,
        raw: message,
        isRegularMessage: true
      }
    };
  }

  // Status update or other non-message webhook
  return {
    json: {
      messageType: 'status_update',
      isRegularMessage: true,
      raw: body
    }
  };
}

// This is an encrypted Flow request - decrypt it
function decryptRequest(body) {
  const { encrypted_aes_key, encrypted_flow_data, initial_vector } = body;

  const decryptedAesKey = crypto.privateDecrypt(
    {
      key: privateKey,
      passphrase: PASSPHRASE,
      oaepHash: 'sha256',
      padding: crypto.constants.RSA_PKCS1_OAEP_PADDING
    },
    Buffer.from(encrypted_aes_key, 'base64')
  );

  const flowDataBuffer = Buffer.from(encrypted_flow_data, 'base64');
  const ivBuffer = Buffer.from(initial_vector, 'base64');

  const authTag = flowDataBuffer.subarray(-16);
  const encryptedData = flowDataBuffer.subarray(0, -16);

  const decipher = crypto.createDecipheriv('aes-128-gcm', decryptedAesKey, ivBuffer);
  decipher.setAuthTag(authTag);

  const decrypted = Buffer.concat([
    decipher.update(encryptedData),
    decipher.final()
  ]);

  return {
    decryptedData: JSON.parse(decrypted.toString('utf8')),
    aesKey: decryptedAesKey,
    iv: ivBuffer
  };
}

function encryptResponse(response, aesKey, iv) {
  const flippedIv = Buffer.alloc(iv.length);
  for (let i = 0; i < iv.length; i++) {
    flippedIv[i] = ~iv[i] & 0xff;
  }
  const cipher = crypto.createCipheriv('aes-128-gcm', aesKey, flippedIv);
  const encrypted = Buffer.concat([
    cipher.update(JSON.stringify(response), 'utf8'),
    cipher.final(),
    cipher.getAuthTag()
  ]);
  return encrypted.toString('base64');
}

